from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes

def open_(key, iv, ct, tag):
    mode = modes.GCM(iv, tag, min_tag_length=len(tag))
    d = Cipher(algorithms.AES(key), mode).decryptor()
    return d.update(ct) + d.finalize()

def verify(pub, sig: bytes, msg: bytes) -> bool:
    try:
        pub.verify(sig[:64], msg)
        return True
    except Exception:
        return False

